import { describe, expect, test } from 'bun:test';
import { z } from 'zod';
import fixtures from './fixtures/legacy-skill-schemas.json';
import { normalizeSkillSchema, stringToZod } from './zodToString';

// golden results generated by unpatched zodex@3.0.0 + zod@3.25.76, not by the replacement reader.
const cases = z
	.array(
		z.object({
			name: z.string(),
			legacy: z.json(),
			cases: z.array(z.object({ input: z.json(), success: z.boolean(), output: z.json().optional() })),
		}),
	)
	.parse(fixtures);

function decode(value: z.JSONType): unknown {
	if (Array.isArray(value)) return value.map(decode);
	if (value !== null && typeof value === 'object') {
		if (typeof value.$bigint === 'string') return BigInt(value.$bigint);
		if (value.$undefined === true) return undefined;
		return Object.fromEntries(Object.entries(value).map(([key, child]) => [key, decode(child)]));
	}
	return value;
}

describe('zodex 3 compatibility oracle', () => {
	for (const fixture of cases) {
		test(fixture.name, () => {
			const legacy = JSON.stringify(fixture.legacy);
			for (const stored of [legacy, normalizeSkillSchema(legacy)]) {
				const schema = stringToZod(stored);
				for (const example of fixture.cases) {
					const actual = schema.safeParse(decode(example.input));
					expect(actual.success).toBe(example.success);
					if (actual.success && example.success) expect(actual.data).toEqual(decode(example.output ?? null));
				}
			}
		});
	}
});
